 */
export async function listLiveIssuesForProject(
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly Issue[]> {
  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(
        ...compact(
          orgPredicate(issues.orgId, orgId),
          eq(issues.projectId, projectId),
          livePredicate(issues.archivedAt, {}),
        ),
      ),
    )
    .orderBy(issues.number, issues.createdAt, issues.id)
    .all();

  const labels: Record<string, readonly { id: LabelId }[]> = {};
  const CHUNK = 500;
  for (let at = 0; at < rows.length; at += CHUNK) {
    Object.assign(
      labels,
      await listLabelsForIssues(
        orgId,
        rows.slice(at, at + CHUNK).map((row) => row.id as IssueId),
      ),
    );
  }

  return rows.map((row) =>
    toIssue(row, (labels[row.id] ?? []).map((label) => label.id)),
  );
}

