sub(p,'''export async function updateProject(''','''/**
 * Clones a project, optionally with its issues (ADR 0012).
 *
 * The clone is a fresh start: it copies what describes the work (the project's
 * description, visibility, colour and lead; each live issue's title,
 * description, priority, estimate, due date and labels) and resets everything
 * that records progress. Every gate — both permissions, the project quota and
 * the per-project issue quota for the whole batch — is checked before the
 * first write, so a refused clone leaves nothing behind.
 *
 * Only `project.cloned` is published. The audit entry, the search index and
 * the usage meters are brought up to date here, because no `project.created`
 * or `issue.created` is announced for the copies.
 */
export async function cloneProject(
  actor: Actor,
  input: CloneProjectInput,
): Promise<Project> {
  assertOrgScope(actor, input.orgId);

  const source = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertNotArchived("Project", source.id, source);
  assertCan(actor, "project:read", projectResource(source));
  assertCan(actor, "project:create", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  const used = await projectRepo.countProjects(input.orgId);
  if (wouldExceedLimit(org.plan, "projects", used)) {
    throw new Error(
      `Plan ${org.plan} allows ${used} projects; upgrade to add another`,
    );
  }

  const sourceIssues = input.includeIssues
    ? await issueRepo.listLiveIssuesForProject(input.orgId, source.id)
    : [];
  if (
    sourceIssues.length > 0 &&
    wouldExceedLimit(org.plan, "issuesPerProject", 0, sourceIssues.length)
  ) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${input.key}; ` +
        `${sourceIssues.length} issues cannot be copied`,
    );
  }

  const parsedStatus = issueStatusSchema.safeParse(
    org.settings.defaultIssueStatus,
  );
  const status = parsedStatus.success ? parsedStatus.data : "backlog";

  const project = await projectRepo.insertProject({
    orgId: input.orgId,
    name: input.name,
    slug: input.slug,
    key: input.key,
    description: source.description,
    visibility: source.visibility,
    leadId: source.leadId,
    color: source.color,
    targetDate: null,
  });

  const copies: Issue[] = [];
  for (const issue of sourceIssues) {
    copies.push(
      await issueRepo.insertIssue(
        {
          orgId: input.orgId,
          projectId: project.id,
          title: issue.title,
          description: issue.description,
          status,
          priority: issue.priority,
          assigneeId: null,
          parentId: null,
          estimate: issue.estimate,
          dueAt: issue.dueAt,
          labelIds: [...issue.labelIds],
        },
        actor.userId,
        copies.length + 1,
      ),
    );
  }

  await indexProject(input.orgId, project);
  for (const copy of copies) await indexIssue(input.orgId, copy);

  await usageRepo.incrementUsage(input.orgId, {
    projectsUsed: 1,
    issuesUsed: copies.length,
  });

  await record(input.orgId, "project.cloned", {
    actorId: actor.userId,
    subjectKind: "project",
    subjectId: project.id,
    projectId: project.id,
    summary: `Cloned project ${source.name} as ${project.name} with ${copies.length} issues`,
    metadata: { sourceProjectId: source.id, issuesCopied: copies.length },
  });

  await emit("project.cloned", {
    ...actorEnvelope(actor),
    projectId: project.id,
    sourceProjectId: source.id,
    issuesCopied: copies.length,
  });

  return project;
}

