import * as issueRepo from "@/server/repositories/issue-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import { registerEventHandlers, unregisterEventHandlers } from "@/server/services/event-registry";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); registerEventHandlers(); });
afterAll(() => { unregisterEventHandlers(); cleanup(); });
it("clones", async () => {
  const t = await createTenant("clonetmp", "growth");
  const a = await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { title: "First one", assigneeId: t.userIds.admin }));
  const b = await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { title: "Second one" }));
  await issueService.createIssue(t.actors.member, issueInput(t.org.id, t.project.id, { title: "Third one" }));
  await issueService.changeIssueStatus(t.actors.member, { orgId: t.org.id, issueId: a.id, status: "done" });
  await issueService.archiveIssue(t.actors.admin, t.org.id, b.id);
  const before = await usageRepo.getUsage(t.org.id);
  const idx = await searchRepo.countIndexed(t.org.id);
  const seen: unknown[] = [];
  const off = subscribe("project.cloned", (p) => { seen.push(p); });
  const clone = await projectService.cloneProject(t.actors.admin, { orgId: t.org.id, projectId: t.project.id, name: "Copy", slug: "platform", key: "CPY", includeIssues: true });
  off();
  expect(clone.slug).toBe("platform-2");
  const issues = await issueRepo.listLiveIssuesForProject(t.org.id, clone.id);
  expect(issues.map((i) => [i.number, i.title, i.status, i.assigneeId, i.authorId])).toEqual([
    [1, "First one", "backlog", null, t.userIds.admin],
    [2, "Third one", "backlog", null, t.userIds.admin],
  ]);
  const after = await usageRepo.getUsage(t.org.id);
  expect(after.projectsUsed - before.projectsUsed).toBe(1);
  expect(after.issuesUsed - before.issuesUsed).toBe(2);
  expect(await searchRepo.countIndexed(t.org.id)).toBe(idx + 3);
  expect(seen).toHaveLength(1);
  const acts = await activityRepo.listActivityForSubject(t.org.id, "project", clone.id);
  console.log(JSON.stringify(acts), JSON.stringify(seen));
});
